// VYRO E2EE interop test (Node): proves the TypeScript WebCrypto client
// and the Go backend implement the same VYRO E2EE v1 protocol.
//
// Direction 1 (Go -> TS): decrypt the Go-produced vector
//   e2ee-vector.json (Alice's first message to Bob, generated by the
//   Go e2ee package test).
// Direction 2 (TS -> Go): the TS client initiates a session as Alice to
//   Bob (keys from the same vector), encrypts a message, writes a fixture
//   for the Go verifier (backend/cmd/e2ee-verify), which must print the
//   same plaintext.
//
// Run (from web/):
//   npx tsc lib/e2ee.ts lib/b64.ts --outDir /tmp/e2ee-interop --module commonjs --target es2022 --lib es2022,dom --skipLibCheck
//   cp lib/e2ee.interop.cjs /tmp/e2ee-interop/test.cjs && node /tmp/e2ee-interop/test.cjs
// Exits non-zero on any mismatch. The TS->Go direction writes a
// fixture for the Go verifier (see docs/SECURITY.md for the command);
// the Go side is proven separately by backend/internal/e2ee tests.
const fs = require("fs");
const { b64decode, b64encode } = require("./b64.js");
const e2ee = require("./e2ee.js");

const vec = JSON.parse(fs.readFileSync(require("path").join(__dirname, "e2ee-vector.json"), "utf8"));

async function main() {
  // --- Direction 1: Go -> TS ---
  const b64url = (b) => Buffer.from(b).toString("base64url");
  const bobIdent = {
    dhPriv: b64decode(vec.bob_dh_priv),
    dhPub: b64decode(vec.bob_dh_pub),
    signPrivJwk: {
      d: b64url(b64decode(vec.bob_sign_priv).subarray(0, 32)),
      x: b64url(b64decode(vec.bob_sign_pub)),
    },
    signPub: b64decode(vec.bob_sign_pub),
  };
  const bobSpk = {
    id: 1,
    priv: b64decode(vec.bob_spk_priv),
    pub: b64decode(vec.bob_spk_pub),
    signature: new Uint8Array(64), // not used by receiveInit
  };
  const bobOpk = {
    id: vec.envelope.opk,
    priv: b64decode(vec.bob_opk_priv),
    pub: b64decode(vec.bob_opk_pub),
  };
  const bobSess = await e2ee.receiveInitSession(
    bobIdent,
    bobSpk,
    bobOpk,
    b64decode(vec.envelope.ik),
    b64decode(vec.envelope.ek),
    "alice",
    "default",
  );
  const pt1 = await bobSess.decrypt(vec.envelope);
  if (pt1 !== vec.plaintext) {
    console.error(`Go->TS FAIL: decrypted ${JSON.stringify(pt1)}, want ${JSON.stringify(vec.plaintext)}`);
    process.exit(1);
  }
  console.log("Go->TS interop: OK — TS decrypted the Go envelope:", JSON.stringify(pt1));

  // --- Direction 2: TS -> Go ---
  // TS Alice initiates to Bob's bundle. The bundle signature is made
  // in TS with Bob's signing seed (test-only: we own Bob's keys here).
  const aliceIdent = {
    dhPriv: b64decode(vec.alice_dh_priv),
    dhPub: b64decode(vec.alice_dh_pub),
    signPrivJwk: { d: b64url(new Uint8Array(32)), x: b64url(b64decode(vec.alice_sign_pub)) },
    signPub: b64decode(vec.alice_sign_pub),
  };
  const bobBundle = {
    user_id: "bob",
    device_id: "default",
    dh_pub: vec.bob_dh_pub,
    sign_pub: vec.bob_sign_pub,
    spk_pub: vec.bob_spk_pub,
    spk_id: 1,
    spk_sig: "", // filled below
    one_time_prekey: { id: 7, pub: vec.bob_opk_pub },
  };
  // Sign Bob's SPK with Bob's Ed25519 seed via the TS helper path:
  // generate a signed pre-key is not possible without the seed inside
  // the module, so sign here with Node's own Ed25519 (same primitive).
  const nodeCrypto = require("crypto");
  const bobEdKey = nodeCrypto.createPrivateKey({
    key: Buffer.concat([
      Buffer.from([0x30, 0x2e, 0x02, 0x01, 0x00, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x04, 0x22, 0x04, 0x20]),
      Buffer.from(b64decode(vec.bob_sign_priv).subarray(0, 32)),
    ]),
    format: "der",
    type: "pkcs8",
  });
  const sig = nodeCrypto.sign(null, Buffer.from(b64decode(vec.bob_spk_pub)), bobEdKey);
  bobBundle.spk_sig = b64encode(new Uint8Array(sig));
  if (!(await e2ee.verifyBundle(bobBundle))) {
    console.error("TS->Go FAIL: TS could not verify the bundle it built");
    process.exit(1);
  }
  const aliceSess2 = await e2ee.initiateSession(aliceIdent, bobBundle);
  const plaintext2 = "TS->Go: سلام VYRO — interop test";
  const env2 = await aliceSess2.encrypt(plaintext2);
  const fixture = {
    bob_dh_priv: vec.bob_dh_priv,
    bob_dh_pub: vec.bob_dh_pub,
    bob_sign_priv: vec.bob_sign_priv,
    bob_sign_pub: vec.bob_sign_pub,
    bob_spk_priv: vec.bob_spk_priv,
    bob_spk_pub: vec.bob_spk_pub,
    bob_spk_id: 1,
    bob_opk_priv: vec.bob_opk_priv,
    bob_opk_pub: vec.bob_opk_pub,
    bob_opk_id: 7,
    envelope: env2,
    expected: plaintext2,
  };
  fs.writeFileSync("/tmp/e2ee-interop/ts-envelope.json", JSON.stringify(fixture, null, 2));
  console.log("TS->Go fixture written: /tmp/e2ee-interop/ts-envelope.json");
  console.log("TS->Go interop: TS encrypted; run the Go verifier to confirm.");
}

main().catch((e) => {
  console.error("interop test error:", e);
  process.exit(1);
});
